previewCss:
.darma-loader-darma-b13-bowling-strike { --accent: var(--loader-color, #dc2626); --accent-2: var(--loader-secondary-color, #7c3aed); width: var(--loader-size, 120px); height: calc(var(--loader-size, 120px) * .58); position: relative; }
.darma-loader-darma-b13-bowling-strike::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 7%; border-radius: 999px; background: linear-gradient(90deg, color-mix(in srgb, #000 12%, var(--accent-2)), var(--accent-2)); }
.darma-loader-darma-b13-bowling-strike span { position: absolute; bottom: 7%; width: 11%; height: 44%; border-radius: 50% 50% 22% 22% / 34% 34% 14% 14%; background: linear-gradient(#f8fafc 0 40%, var(--accent) 40% 56%, #f8fafc 56%); animation: darma-loader-darma-b13-bowling-strike-knock calc(var(--loader-speed, 1s) * 2.6) ease-out infinite; }
.darma-loader-darma-b13-bowling-strike span:nth-child(1) { right: 8%; }
.darma-loader-darma-b13-bowling-strike span:nth-child(2) { right: 21%; animation-delay: calc(var(--loader-speed, 1s) * .05); }
.darma-loader-darma-b13-bowling-strike span:nth-child(3) { right: 34%; animation-delay: calc(var(--loader-speed, 1s) * .1); }
.darma-loader-darma-b13-bowling-strike .darma-loader-darma-b13-bowling-strike__ball { position: absolute; bottom: 7%; left: 0; width: calc(var(--loader-size, 120px) * .2); height: calc(var(--loader-size, 120px) * .2); border-radius: 50%; background: radial-gradient(circle at 34% 30%, color-mix(in srgb, #fff 34%, var(--accent-2)), color-mix(in srgb, #000 28%, var(--accent-2))); animation: darma-loader-darma-b13-bowling-strike-roll calc(var(--loader-speed, 1s) * 2.6) linear infinite; }
@keyframes darma-loader-darma-b13-bowling-strike-roll { 0% { opacity: 0; transform: translateX(-24%) rotate(0deg); } 8% { opacity: 1; } 56% { transform: translateX(calc(var(--loader-size, 120px) * .58)) rotate(540deg); } 68% { opacity: 0; transform: translateX(calc(var(--loader-size, 120px) * .68)) rotate(600deg); } 100% { opacity: 0; transform: translateX(calc(var(--loader-size, 120px) * .68)) rotate(600deg); } }
@keyframes darma-loader-darma-b13-bowling-strike-knock { 0%, 54% { transform: translate(0, 0) rotate(0deg); } 70% { transform: translate(calc(var(--loader-size, 120px) * .09), calc(var(--loader-size, 120px) * -.07)) rotate(62deg); } 84% { opacity: .5; transform: translate(calc(var(--loader-size, 120px) * .15), 0) rotate(92deg); } 85%, 100% { opacity: 1; transform: translate(0, 0) rotate(0deg); } }

